import './App.css';
import Modal from './Components/modal.js'
import { AddPuzzleModal } from './Components/modalDisplays.js';

import { useEffect, useState } from 'react'

import { auth, app, db } from './firebase.js';
import { signInWithPopup, GoogleAuthProvider, onAuthStateChanged, signOut } from 'firebase/auth';
import { doc, collection, setDoc, getDoc, addDoc, updateDoc, arrayUnion, arrayRemove, query, where, orderBy } from 'firebase/firestore';

import { useAuthState } from 'react-firebase-hooks/auth';


function App() {

  const [user] = useAuthState(auth);

  const [changedPuzzleList, setChangedPuzzleList] = useState(0);
  const [puzzleList, setPuzzleList] = useState([]);

  const [modal, setModal] = useState(false);
  const [modalDisplay, setModalDisplay] = useState(null);

  const DeletePuzzle = async (puzzle) => {
    const userRef = doc(db, 'users', user.uid);
    await updateDoc(userRef, {
      puzzles: arrayRemove(puzzle)
    });
    setChangedPuzzleList(Math.random());
    console.log(changedPuzzleList);
  }

  const toggleModal = (event) => {

    if (event===undefined) {
      setModalDisplay(<p>Done</p>);
    }
    else {
    switch(event.target.className) {
      case 'add':
        setModalDisplay(<AddPuzzleModal
          user={user}
          changedPuzzleList={changedPuzzleList}
          setChangedPuzzleList={setChangedPuzzleList}
          toggleModal={toggleModal} />);
        break;
      case 'delete':
        DeletePuzzle(event.target.value)
        return;
      default:
        setModalDisplay(null);
    }
    }
    setModal(!modal);
  };


  useEffect(() => {
    const fetchData = async () => {
      try {
        const userRef = doc(db, 'users', user.uid);
        const userSnap = await getDoc(userRef);
        console.log(userSnap.data().puzzles);
        setPuzzleList(userSnap.data().puzzles);
      } catch(error) {
        console.log(error);
      }
      }

  fetchData();
  },[ changedPuzzleList, user]);

  return (
    <div className="App">
        <header>
          <img className='logo' src='../logo.svg' alt='logo'/>
          <h1 className='title'>PuzzleDiary</h1>
          {user ? <>
          <button onClick={toggleModal} className='add'><img className='addPuzzlesIcon'src="../addPuzzlesIcon.svg" alt='Add Button'/></button>
          <div className='userArea'>
            <img className='userPhoto' src={user.photoURL} alt='User Profile'/>
            <SignOutButton /> 
          </div>
           </>
           : <SignInButton />}
          <Modal modal={modal} toggleModal={toggleModal} modalDisplay={modalDisplay}/>
        </header>

        <div className='body'>
          {user ? 
          <>
           <PuzzlesBoard
           user={user}
           puzzleList={puzzleList}
           showDelete={true}
           toggleModal={toggleModal}
           setPuzzleList={setPuzzleList}
           setChangedPuzzleList={setChangedPuzzleList} /> 
           </>
           : null }


        </div>
    </div>
  );
}

function SignInButton() {
  const SignIn = () => {
    const provider = new GoogleAuthProvider();
    signInWithPopup(auth, provider)
    .then(async (result) => {
      let user = result.user
      const userRef = doc(db, 'users', user.uid);
      const userSnap = await getDoc(userRef);
      if(!userSnap.exists()) {
        await setDoc(doc(db, 'users', user.uid), {
          email: user.email,
          name: user.displayName,
          puzzles: []
        });
      }
    });
  }

  return (
    <button className='signIn' onClick={SignIn}>Sign In With Google</button>
  )
}

function SignOutButton() {
  const SignOut = () => {
    signOut(auth);
  }
  return auth.currentUser && (
    <button className='signOut' onClick={SignOut}>Sign Out</button>
  )
}

 function PuzzlesBoard(props) {


  const updatePuzzleStatuses = async (event) => {
      var tempPuzzleList = props.puzzleList.slice();
      for(let i = 0; i < tempPuzzleList.length; i++) 
        if(tempPuzzleList[i] === event.target.value) {
          if(tempPuzzleList[i].substring(0,1) === event.target.dataset.color)
            tempPuzzleList[i] = 'X' + tempPuzzleList[i].substring(1);
          else 
            tempPuzzleList[i] = event.target.dataset.color + tempPuzzleList[i].substring(1);
          break;
        }

      const userRef = doc(db, 'users', props.user.uid);
      props.setPuzzleList(tempPuzzleList);

      await updateDoc(userRef, {
        puzzles:  tempPuzzleList
      });

      props.setChangedPuzzleList(Math.random());
  }

  if(!props.puzzleList) return (null);

    return (
    <div className='puzzleBoard'>
      {props.puzzleList.map(puzzle => <PuzzleCard puzzle={puzzle}
       AddPuzzle={props.AddPuzzle}
       showDelete={props.showDelete}
       toggleModal={props.toggleModal}
       updatePuzzleStatuses={updatePuzzleStatuses}/>)}
    </div>
  )
}

function PuzzleCard(props) {

  const changePuzzleStatus = (color) => {
    if(puzzleStatus === color) puzzleStatus = 'X'
    else puzzleStatus = color;
  }
  let puzzleStatus = props.puzzle.substring(0,1);
  let puzzleURL = props.puzzle.substring(1, props.puzzle.indexOf(' '));
  let puzzleDomain = puzzleURL.substring(8, puzzleURL.indexOf('/', 8) !== -1 ? puzzleURL.indexOf('/', 8) : puzzleURL.length);
  let puzzleTitle = props.puzzle.substring(props.puzzle.indexOf(' ')+1);

  if(puzzleDomain.substring(0,4) === 'www.')
    puzzleDomain = puzzleDomain.substring(4);


  const [faviconLink, setFaviconLink] = useState(`https://t1.gstatic.com/faviconV2?client=SOCIAL&type=FAVICON&fallback_opts=TYPE,SIZE,URL&url=${puzzleURL}&size=128`);
  useEffect(() => {
    setFaviconLink(`https://t1.gstatic.com/faviconV2?client=SOCIAL&type=FAVICON&fallback_opts=TYPE,SIZE,URL&url=${puzzleURL}&size=128`);
  }, [props, puzzleURL]);

  return (
    <div className={`puzzleCard ${puzzleStatus} ${props.showDelete}`}>
      <a href={puzzleURL} target="_blank" rel="noopener noreferrer">
      <img className='favicon'src={faviconLink} alt='Site Icon'/>
      </a>
      <p>{puzzleTitle}</p>
      <h5>{puzzleDomain}</h5>
      {props.showDelete ? 
      <>
      <button className='completedPuzzle' data-color='G' value={props.puzzle} onClick={(event) => {props.updatePuzzleStatuses(event);changePuzzleStatus('G')}}>
        <img className='successIcon' src='../successIcon.svg' alt='success'/>
      </button>
      <button className='failedPuzzle' data-color='R' value={props.puzzle} onClick={(event) => {props.updatePuzzleStatuses(event);changePuzzleStatus('R')}}>
        <img className='failIcon' src='../failIcon.svg' alt='fail'/>
      </button>
      <button className='delete' value={props.puzzle} onClick={props.toggleModal}><img className='trashIcon' src='../trashIcon.svg' alt='trash'/></button>
      </>
      :  
      <button className='addFromRecs' value={props.puzzle} onClick={props.AddPuzzle}><img className='addIcon' src='addIcon.svg' alt='Add Button'/></button>}
    </div>
  )

}

export { PuzzlesBoard };
export default App;
